package com.uteq.software.app.Utilsimport android.os.Bundleimport android.widget.ArrayAdapterimport android.widget.AutoCompleteTextViewimport android.widget.ListViewimport androidx.activity.enableEdgeToEdgeimport androidx.appcompat.app.AppCompatActivityimport androidx.core.view.ViewCompatimport androidx.core.view.WindowInsetsCompatimport androidx.lifecycle.lifecycleScopeimport com.uteq.software.app.Adapters.AlumnoAdapterimport com.uteq.software.app.Models.Alumnoimport com.uteq.software.app.Models.Materiaimport com.uteq.software.app.Rimport com.uteq.software.app.Services.SupabaseErrorHandlerimport com.uteq.software.app.Services.SupabaseManagerimport io.github.jan.supabase.exceptions.RestExceptionimport io.github.jan.supabase.postgrest.fromimport io.github.jan.supabase.postgrest.query.Orderimport kotlinx.coroutines.launchclass MainActivity2 : AppCompatActivity() {    private lateinit var actvNiveles: AutoCompleteTextView    private lateinit var actvMaterias: AutoCompleteTextView    private lateinit var listView: ListView    private val categorias by lazy { resources.getStringArray(R.array.niveles).toList() }    private var materiasFiltradas = listOf<Materia>()    private var alumnos = ArrayList<Alumno>()    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        enableEdgeToEdge()        setContentView(R.layout.activity_main2)        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)            insets        }        actvNiveles = findViewById(R.id.actvListaNiveles)        actvMaterias = findViewById(R.id.actvListaMaterias)        listView = findViewById(R.id.lvAlumnos)        configurarSpinnerSemestre()        configurarListeners()        lifecycleScope.launch {            cargarDatosIniciales()        }    }    private fun configurarSpinnerSemestre() {        val adapter = ArrayAdapter(            this,            android.R.layout.simple_dropdown_item_1line,            categorias        )        actvNiveles.setAdapter(adapter)        actvNiveles.setText(categorias[5], false)    }    private fun configurarListeners() {        actvNiveles.setOnItemClickListener { _, _, position, _ ->            actvMaterias.setText("")            lifecycleScope.launch {                cargarMaterias(position + 1)            }        }        actvMaterias.setOnItemClickListener { _, _, _, _ ->            actualizarListaAlumnos()        }    }    private suspend fun cargarDatosIniciales() {        try {            alumnos = ArrayList(                SupabaseManager.client                    .from("alumnos")                    .select {                        order("nombres", Order.ASCENDING)                    }                    .decodeList<Alumno>()            )            val categoriaActual = actvNiveles.text.toString()            val nivel = if (categoriaActual.isNotBlank()) {                nivelDesdeCategoria(categoriaActual)            } else {                6            }            cargarMaterias(nivel)        } catch (e: RestException) {            SupabaseErrorHandler.show(this@MainActivity2, e)        }    }    private fun nivelDesdeCategoria(categoria: String): Int {        val index = categorias.indexOf(categoria)        return if (index >= 0) index + 1 else 6    }    private suspend fun cargarMaterias(nivel: Int) {        try {            materiasFiltradas = SupabaseManager.client                .from("materias")                .select {                    filter {                        eq("nivel", nivel)                    }                    order("nombre", Order.ASCENDING)                }                .decodeList<Materia>()            val nombres = materiasFiltradas.map { it.nombre ?: "" }            val adapter = ArrayAdapter(                this@MainActivity2,                android.R.layout.simple_spinner_dropdown_item,                nombres            )            actvMaterias.setAdapter(adapter)            if (nombres.isNotEmpty()) {                actvMaterias.setText(nombres[0], false)            } else {                actvMaterias.setText("", false)            }            actualizarListaAlumnos()        } catch (e: RestException) {            SupabaseErrorHandler.show(this@MainActivity2, e)        }    }    private fun actualizarListaAlumnos() {        listView.adapter = AlumnoAdapter(this, alumnos)    }}